<script lang="ts" module>

  import type { DynamicLayoutNodeInfo } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { CalculatorIcon } from "@lucide/svelte";

  export const CalculatorNodeInfo: DynamicLayoutNodeInfo = {
    nodeType: "calculator",
    schemaParts: () => [],
    iconComponent: CalculatorIcon
  };
</script>
<script lang="ts">
  import { type ComponentProps } from "$lib/components/composites/dynamic-layout";
  import { ensurePath } from "$lib/blocks/data-utils/ensurePath";
  import { NodePersistenceContext } from "../../contexts/nodePersistence.context";
  import { create, all } from "mathjs";
  import { SvelteMap } from "svelte/reactivity";

  const math = create(all);

  let { layoutContext }: ComponentProps = $props();

  let node = $derived(layoutContext.node);
  let nodeProps = $derived(node.nodeConfig as { expressions: string[] });

  let expressions = $state(nodeProps?.expressions ?? [""]);


// This is a minimal set of functions to look like a Map.
class CustomMap {
  localScope: Map<string, any>;

  constructor () {
    this.localScope = new SvelteMap()
  }

  get (key: string) {
    // Remember to sanitize your inputs, or use
    // a datastructure that isn't a footgun.
    return this.localScope.get(key)
  }

  set (key: string, value: string) {
    return this.localScope.set(key, value)
  }

  has (key: string) {
    return this.localScope.has(key)
  }

  keys (): Iterator<string> {
    return this.localScope.keys()
  }
}

/*
 * This is a more fully featured example, with all methods
 * used in mathjs.
 *
 */
class AdvancedCustomMap extends CustomMap {
  constructor (private parentScope?: CustomMap) {
    super()
  }

  get (key: string) {
    return this.localScope.get(key) ?? this.parentScope?.get(key)
  }

  has (key: string) {
    return this.localScope.has(key) ?? this.parentScope?.get(key)
  }

  keys (): Iterator<string> {
    if (this.parentScope) {
      const parentKeys: string[] = [];

      const it = this.parentScope.keys();
      let key = '';
      while ( key = it.next().value) {
        parentKeys.push(key);
      }

      return new Set([...this.localScope.keys(), ...parentKeys]).keys()
    } else {
      return this.localScope.keys()
    }
  }

  delete (key: string) {
    return this.localScope.delete(key)
  }

  clear () {
    return this.localScope.clear()
  }

  toString () {
    return this.localScope.toString()
  }
}


  let scope = new AdvancedCustomMap();

  const nodePersistenceContext = NodePersistenceContext.get();

  function addExpression() {
    expressions = [...expressions, ""];
    saveExpressions();
  }

  function updateExpression(index: number, value: string) {
    expressions[index] = value;
    saveExpressions();
  }

  function saveExpressions() {
    nodePersistenceContext.applyChangesToNode(layoutContext, node.id, (receivedNode) => {
      ensurePath(receivedNode, "nodeConfig");
      receivedNode.nodeConfig.expressions = expressions;
    });
  }

  function calculateResult(expression: string) {
    try {
      return math.evaluate(expression, scope);
    } catch (error) {
      return "Error";
    }
  }
</script>

{JSON.stringify(scope.localScope)}

<div>
  {#each expressions as expression, index}
    <div class="expression-row">
      <input
        type="text"
        bind:value={expressions[index]}
        on:input={(e) => updateExpression(index, e.target.value)}
      />
      <span class="result">{calculateResult(expression)}</span>
    </div>
  {/each}
  <button on:click={addExpression}>Add Expression</button>
</div>

<style>
  .expression-row {
    display: flex;
    align-items: center;
    margin-bottom: 0.5rem;
  }

  .expression-row input {
    flex: 1;
    margin-right: 0.5rem;
  }

  .result {
    min-width: 100px;
    text-align: right;
  }
</style>
