<script lang="ts" module>
  import type { JsonSchemaParts, SchemaPartsGenerator } from "./jsonSchemaTypes";
  import type { LucideIconsKeyOf } from "$lib/components/composites/lucide-svelte-icons/lazy-icons.svelte.js";
  import { type ButtonVariant } from "$lib/components/ui/button";
  import { ButtonVariantValues } from "$lib/components/ui/button";
  import { dependableBooleanProperty, dependableEnumProperty } from "$lib/blocks/svelte-jsonschema-form/schema-utils";
  import { hasTitleSchema } from "./shared-schemas/title-schema";
  import type {
    DynamicLayoutNode,
    DynamicLayoutNodeInfo
  } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { LinkIcon } from "@lucide/svelte";

  interface GenericLinkProps {
    href: string;
    target?: string;
  }

  type NormalIconOptions =
    {
      type: "lucide-icon";
      icon: LucideIconsKeyOf;
    } | {
    type: "emoji";
    emoji: string;
  } | {
    type: "url";
    url: string;
  }

  type IconByLinkUrl = {
    type: "link-url";
  }

  export interface LinkNodeProps extends GenericLinkProps {
    variant: ButtonVariant;

    showIcon: boolean;
    iconSide?: "left" | "right";
    iconOptions?: NormalIconOptions | IconByLinkUrl;
  }


  const isLinkNodeSchema = () => (): JsonSchemaParts => {
    const iconTypeProp = dependableEnumProperty({
      iconOptions: {
        type: "string",
        enum: ["lucide-icon", "emoji", "url", "link-url"],
        title: "Icon Type"
      }
    }, {
      "lucide-icon": {
        icon: {
          type: "string",
          title: "Icon"
        }
      },
      "emoji": {
        emoji: {
          type: "string",
          title: "Emoji"
        }
      },
      "url": {
        url: {
          type: "string",
          title: "URL"
        }
      },
      "link-url": {
        "helpText": {
          title: "",
          "description": "Trying to get the Links favicon. If it doesn't work, it will show a globe icon.",
          "type": "null"
        }
      }
    });

    const showIconProp = dependableBooleanProperty({
        showIcon: {
          type: "boolean",
          title: "Show Icon"
        }
      }, {}, {
        iconSide: {
          type: "string",
          enum: ["left", "right"],
          title: "Icon Side"
        },
        ...iconTypeProp.property

      },
      iconTypeProp.dependencyEntry
    );


    return {
      dataTab: "general",
      schemaProperties: {
        linkOptions: {
          type: "object",
          title: "Link Options",
          properties: {
            href: {
              type: "string",
              title: "URL"
            },
            target: {
              type: "string",
              title: "Target"
            },
            variant: {
              type: "string",
              enum: ButtonVariantValues,
              title: "Variant"
            },
            ...showIconProp.property
          },

          dependencies: {
            ...showIconProp.dependencyEntry
          }
        }
      },
      requiredProperties: [],
      uiSchemaProperties: {},
      getFormValuesByNode: (node: DynamicLayoutNode) => {
        const nodeProps = node.nodeConfig as LinkNodeProps;
        return {
          linkOptions: {
            href: nodeProps.href,
            target: nodeProps.target,
            variant: nodeProps.variant,
            showIcon: nodeProps.showIcon,
            iconSide: nodeProps.iconSide,
            iconOptions: nodeProps.iconOptions?.type,
            ...nodeProps.iconOptions
          }
        };
      },
      setToNode: (node: DynamicLayoutNode, values: any) => {
        node.nodeConfig.href = values.linkOptions.href;
        node.nodeConfig.target = values.linkOptions.target;
        node.nodeConfig.variant = values.linkOptions.variant;
        node.nodeConfig.showIcon = values.linkOptions.showIcon;
        node.nodeConfig.iconSide = values.linkOptions.iconSide;

        node.nodeConfig.iconOptions ??= {};
        node.nodeConfig.iconOptions.type = values.linkOptions.iconOptions;

        switch (values.linkOptions.iconOptions) {
          case "lucide-icon":
            node.nodeConfig.iconOptions.icon = values.linkOptions.icon;
            break;
          case "emoji":
            node.nodeConfig.iconOptions.emoji = values.linkOptions.emoji;
            break;
          case "url":
            node.nodeConfig.iconOptions.url = values.linkOptions.url;
            break;
        }
      }
    };
  };

  export const SCHEMA_PARTS: SchemaPartsGenerator = (context) => [
    hasTitleSchema(true),
    isLinkNodeSchema()
  ];

  export const LinkNodeInfo: DynamicLayoutNodeInfo = {
    nodeType: "link",
    schemaParts: SCHEMA_PARTS,
    iconComponent: LinkIcon
  };
</script>
<script lang="ts">
  import { type ComponentProps } from "$lib/components/composites/dynamic-layout";
  import { getLabel } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { Button } from "$lib/components/ui/button";
  import LucideIcon from "$lib/components/composites/lucide-svelte-icons/LucideIcon.svelte";
  import { ButtonActionHandlerContext } from "../../contexts/buttonActionHandler.context";
  import { getFavIconUrl } from "$lib/blocks/utils/favIconUrl";

  let {
    layoutContext
  }: ComponentProps = $props();

  let node = $derived(layoutContext.node);
  let label = $derived(getLabel(layoutContext.node));

  let nodeProps = $derived(node.nodeConfig as LinkNodeProps);

  let variant = $derived(nodeProps?.variant ?? "outline");

  // let nodeAction = $derived(nodeProps?.action);

  let buttonActionHandler = ButtonActionHandlerContext.get();

  function handleClick (e) {
    buttonActionHandler([{
      type: "open_url",
      url: nodeProps.href
    }], layoutContext);
  }


</script>

{#snippet linkIcon ()}
  {#if nodeProps.iconOptions?.type === "lucide-icon"}
    <LucideIcon iconName={nodeProps.iconOptions.icon} />
  {:else if nodeProps.iconOptions?.type === "emoji"}
    <span>{nodeProps.iconOptions.emoji}</span>
  {:else if nodeProps.iconOptions?.type === "url"}
    <img src={nodeProps.iconOptions.url} height="24" width="24" alt="" />
  {:else if nodeProps.iconOptions?.type === "link-url"}
    <img src={getFavIconUrl(nodeProps.href)} height="24" width="24" alt="" />
  {/if}
{/snippet}

<Button variant={variant} onclick={handleClick} style="width: 100%">

  {#if nodeProps.showIcon}
    {#if nodeProps.iconSide === "left"}
      {@render linkIcon()}
    {/if}
  {/if}

  {label}

  {#if nodeProps.showIcon}
    {#if nodeProps.iconSide === "right"}
      {@render linkIcon()}
    {/if}
  {/if}

</Button>
