<script lang="ts" module>
  import type { DynamicLayoutNodeInfo } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { NotebookPen } from "@lucide/svelte";
  import { marked } from "marked";

  export interface NotesNodeConfigProps {
    editModeOption: "full" | "icon";
  }

  export interface NotesNodeDataProps {
    notes: string;
  }

  export const NotesNodeInfo: DynamicLayoutNodeInfo = {
    nodeType: "note",
    schemaParts: () => [
      () => ({
        dataTab: "general",
        schemaProperties: {
          editModeOption: {
            type: "string",
            enum: ["full", "icon"],
            default: "full",
            title: "Edit Mode Option"
          }
        },
        uiSchemaProperties: {},
        requiredProperties: [],
        getFormValuesByNode: (node) => {
          return {
            editModeOption: node.nodeConfig?.editModeOption ?? "full"
          };
        },
        setToNode: (node, values) => {
          node.nodeConfig.editModeOption = values.editModeOption;
        }
      })
    ],
    iconComponent: NotebookPen
  };
</script>

<script lang="ts">
  import { type ComponentProps } from "$lib/components/composites/dynamic-layout";
  import { link } from "$lib/blocks/svelte-utils/linkState.svelte.js";
  import { applyNodeData, getIdPair, getNodeData } from "../../contexts/nodeDataPersistence.svelte.js";
  import LucideIcon from "$lib/components/composites/lucide-svelte-icons/LucideIcon.svelte";
  import { additionalContext } from "../../state/app-state.svelte.js";

  let {
    layoutContext
  }: ComponentProps = $props();

  let editMode = $state(false);

  let textareaElement = $state<HTMLTextAreaElement | null>(null);

  const nodeConfig = $derived(layoutContext.node.nodeConfig as NotesNodeConfigProps);

  const nodeData = getNodeData<NotesNodeDataProps>(layoutContext, { notes: "" });

  const currentNoteData = link(() => nodeData.data);

  function saveNote () {
    applyNodeData(layoutContext, { notes: currentNoteData.current?.notes }, nodeData.nodeDataId);
    editMode = false;
  }

  function adjustTextareaHeight () {
    if (textareaElement) {
      textareaElement.style.minHeight = "auto";
      textareaElement.style.minHeight = `${textareaElement.scrollHeight}px`;
    }
  }

  $effect(() => {
    if (editMode && textareaElement) {
      adjustTextareaHeight();
    }
  });

  function enableEditMode () {
    if (additionalContext.editMode) {
      alert("Edit is disabled in global Edit Mode");
      return;
    }

    editMode = true;
  }

</script>

{#snippet renderNotes (fallbackText: string)}
  <div class="markdown-body text-wrap whitespace-pre-line text-left">

    {@html marked(currentNoteData.current.notes?.trim() || fallbackText) }
  </div>
{/snippet}

<div class="note-wrap">
  {#if editMode}
    <textarea
      class="w-full p-4 bg-primary/10 rounded-md"
      autofocus
      bind:this={textareaElement}
      oninput={(e) => adjustTextareaHeight()}
      bind:value={currentNoteData.current.notes}
      onblur={() => saveNote()}
    ></textarea>
  {:else}
    {#if nodeConfig.editModeOption === 'full'}
      <button class="p-4 bg-primary/10 rounded-md  flex-grow full-mode"
              onclick={enableEditMode}>
        {@render renderNotes("Click to add a note")}
      </button>
    {:else}
      <div class="flex-grow p-4 ">
        {@render renderNotes("Click the edit icon to add a note")}
      </div>
      <button class="ml-2 p-2 bg-primary/10 rounded-md absolute right-0 top-0"
              onclick={enableEditMode}>
        <LucideIcon iconName="Pencil" size="16" color="white"></LucideIcon>
      </button>
    {/if}
  {/if}
</div>

<style>
   textarea {
      width: 100%;
      height: 100%;
   }

   button.full-mode {
      width: 100%;
      height: 100%;
   }

   .note-wrap {
      position: relative;
   }
</style>
