<script lang="ts" module>
  import type { SchemaPartsGenerator } from "../jsonSchemaTypes";
  import { canHaveChildrenSchema } from "../shared-schemas/children-schemas";
  import type { DynamicLayoutNodeInfo } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { ChevronDown } from "@lucide/svelte";
  import { hasTitleSchema } from "../shared-schemas/title-schema";

  export const SCHEMA_PARTS: SchemaPartsGenerator = (context) => [

    hasTitleSchema(true),
    canHaveChildrenSchema,
  ];

  export const CollapsibleNodeInfo: DynamicLayoutNodeInfo = {
    nodeGroup: "LAYOUT",
    nodeType: "collapsible",
    schemaParts: SCHEMA_PARTS,
    iconComponent: ChevronDown
  };
</script>

<script lang="ts">
  import { type ComponentProps } from "$lib/components/composites/dynamic-layout";
  import { getLabel } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import CollapsibleAnimated from "$lib/components/composites/CollapsibleAnimated.svelte";
  import { LocalUiStateHandlerContext } from "../../../contexts/uiStateHandler.context";

  let {
    layoutContext
  }: ComponentProps = $props();

  let node = $derived(layoutContext.node);
  let label = $derived(getLabel(layoutContext.node));

  const uiStateHandler = LocalUiStateHandlerContext.get();

  const savedOpenState = uiStateHandler.getPropHandler(node, "isOpen", node.nodeConfig?.open ?? false);

  let open = $state(savedOpenState.get());

  function setOpenState (isOpen: boolean) {
    open = isOpen;

    if (node.nodeConfig) {
      node.nodeConfig.open = isOpen;
    }

    savedOpenState.set(isOpen);
  }
</script>

<CollapsibleAnimated buttonLabel={label} bind:open={() => open, setOpenState}>
  {@render layoutContext.render.renderChildren(layoutContext)}
</CollapsibleAnimated>
