<script lang="ts" module>
  import type { DynamicLayoutNodeInfo } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { CalendarCheck } from "@lucide/svelte";

  export const YearDoneNodeInfo: DynamicLayoutNodeInfo = {
    nodeType: "yearDone",
    schemaParts: () => [],
    iconComponent: CalendarCheck
  };
</script>

<script lang="ts">
  import { onMount } from "svelte";
  import type { ComponentProps } from "$lib/components/composites/dynamic-layout";

  let {
    layoutContext
  }: ComponentProps = $props();

  let year = new Date().getFullYear();
  let weeksDone = $state(0);
  let percentDone = $state(0);

  function calculateWeeksDone () {
    const now = new Date();
    const start = new Date(year, 0, 1);
    const diff = now.getTime() - start.getTime();
    const oneWeek = 1000 * 60 * 60 * 24 * 7;
    weeksDone = diff / oneWeek;
    percentDone = Math.floor((weeksDone / 52) * 100_00) / 100;
  }

  onMount(() => {
    calculateWeeksDone();
  });
</script>

<style>
   .year-done-node {
      display: flex;
      flex-direction: column;
      align-items: center;
   }

   .weeks {
      display: grid;
      grid-template-columns: repeat(8, 1fr);
      gap: 2px;
      width: 100%;
   }

   .week {
      height: 20px;
      background-color: lightgray;
   }

   .week.done {
      background-color: green;
   }
</style>

<div class="year-done-node">
  <div>{year} is {percentDone}% done</div>
  <div class="weeks">
    {#each Array(56) as _, index}
      <div class="week {index < weeksDone ? 'done' : ''}"></div>
    {/each}
  </div>
</div>
