import {
	type InsertableNodeData, type NodeDataId,
	NodeId,
	type UpdatableNodeData
} from "./evolu/datastructure";
import { evolu } from "./evolu/evolu_instance";
import { getNodeDataByNodeIdListQuery } from "./evolu/queries";
import { queryState } from "./nodeRepository.svelte";



export const NodeDataRepository = {
	addDbNode(node: InsertableNodeData) {
		return evolu.insert('nodeData', node);
	},

	updateDbNode(node: UpdatableNodeData): void {
		evolu.update('nodeData', node);
	},

	getNodesState(nodeIdList: NodeId[]) {
		return queryState(() => getNodeDataByNodeIdListQuery(nodeIdList), evolu, {
		useLoadQueryResult: true
	});
	},

	async deleteNodeDataByNodeId(nodeId: NodeId): Promise<void> {
		const nodeDataEntries = await evolu.loadQuery(getNodeDataByNodeIdListQuery([nodeId]));

		console.info({
			nodeDataEntries
		})

		for (const nodeData of nodeDataEntries) {
			evolu.update('nodeData', { id: nodeData.id, isDeleted: true });
		}
	},

	deleteNodeDataById(nodeDataId: NodeDataId): void {
		evolu.update('nodeData', { id: nodeDataId, isDeleted: true });
	}
};
