<script module lang="ts">
  import { SvelteMap, SvelteSet } from "svelte/reactivity";

  export const ALL_CATEGORIES = new SvelteSet<string>();
  export const SHOW_CATEGORIES = new SvelteMap<string, boolean>();
</script>

<script lang="ts">
  import { additionalContext } from "$lib/state/app-state.svelte";
  import CollapsibleAnimated from "$lib/components/composites/CollapsibleAnimated.svelte";
  import { Badge } from "$lib/components/ui/badge";
  import { colorByHash } from "$lib/blocks/html-utils/colorByHash";

  interface DebugDetailsProps {
    category: string;
    badgeColor?: string;
    pairs: Record<string, string | number>;
    entries?: { key: string; value: unknown }[];
  }

  let {
    category,
    badgeColor,
    pairs,
    entries
  }: DebugDetailsProps = $props();

  const chosenBadgeColor = badgeColor ?? colorByHash(category);

  pairs["created"] = new Date().toLocaleTimeString();

  ALL_CATEGORIES.add(category);

  if (!SHOW_CATEGORIES.has(category)) {
    SHOW_CATEGORIES.set(category, false);
  }
</script>

{#if additionalContext.DEBUG_MODE && SHOW_CATEGORIES.get(category)}
  <CollapsibleAnimated>
    {#snippet buttonSnippet ()}
      {#each Object.entries(pairs) as [key, value]}
        <Badge color={chosenBadgeColor}>{key}: {value}</Badge> &nbsp;
      {/each}

      {category}
    {/snippet}

    {#if entries}
      {#each entries as { key, value }}
        {key}: <br />
        <pre>{JSON.stringify(value, undefined, 2)}</pre>
      {/each}
    {/if}
  </CollapsibleAnimated>
{/if}
