import type { NodeQueryEntry } from './evolu/queries';
import type { DynamicLayoutNode } from '$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types';

// TODO move closer to the repo responses
// TODO figure out hwo in a state reactivity way...
export function convertDbNodeToDynamicLayoutNode(dbNode: NodeQueryEntry): DynamicLayoutNode {
	if (!dbNode) {
		return null;
	}

	const convertedNode: DynamicLayoutNode ={
		...dbNode,
		layoutData: JSON.parse(dbNode.layoutData!),
		nodeConfig: JSON.parse(dbNode.nodeConfig!),

	}

	return convertedNode;
}
