<script lang="ts" module>
  import type {
    SchemaPartsGenerator
  } from "../jsonSchemaTypes";
  import { DataSourceRepository } from "$lib/database/dataSourceRepository.svelte.js";
  import { hasTitleSchema } from "../shared-schemas/title-schema";
  import type { DynamicLayoutNodeInfo } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { SquareDashedKanban } from "@lucide/svelte";
  import { hasDynamicPayloadFields, hasDynamicTypeSchema } from "./dynamicNodeConfigSchemas";

  export const SCHEMA_PARTS: SchemaPartsGenerator = (context) => [
    hasTitleSchema(false),
    hasDynamicPayloadFields,
    hasDynamicTypeSchema(["collapsible", "children"])
  ];

  export const DynamicNodeInfo: DynamicLayoutNodeInfo = {
    nodeGroup: "LAYOUT",
    nodeType: "dynamic",
    schemaParts: SCHEMA_PARTS,
    iconComponent: SquareDashedKanban
  };
</script>


<script lang="ts">
  import {
    type DynamicLayoutNode,
    getLabel
  } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { type ComponentProps, LayoutContext } from "$lib/components/composites/dynamic-layout";
  import { EditModeContext } from "../../../contexts/editMode.context";
  import { Button } from "$lib/components/ui/button";
  import { dialogState } from "../../../dialogs/dialog-state.svelte.js";
  import { getFormValuesByPayloads, setFormValuesToPayload } from "../jsonSchemaCombinators";

  import { NodeRepository } from "$lib/database/nodeRepository.svelte.js";
  import { convertDbNodeToDynamicLayoutNode } from "$lib/database/layoutDbNodeConverter";
  import { getCachedByIdNodeQuery } from "../helpers/cachedQueries.svelte.js";
  import { type DynamicNodeProps, hasDynamicData } from "./dynamicNodeConfigSchemas";
  import type { PayloadContext } from "./dynamic_node_types";
  import DynamicNodeLayout from "./DynamicNodeLayout.svelte";
  import { Inspect } from "svelte-inspect-value";

  let {
    layoutContext
  }: ComponentProps = $props();

  let node = $derived(layoutContext.node);
  let nodeProps = $derived(node.nodeConfig as DynamicNodeProps);
  let label = $derived(getLabel(layoutContext.node));

  let { addChildToNode, inEditMode } = EditModeContext.get();

  function editTemplateEntries () {
    const targetNode = layoutContext.node;

    const componentSchemas = [
      hasDynamicData(nodeProps)
    ];

    if (componentSchemas.length === 0) {
      alert("no component schema yet!");
      return;
    }

    dialogState.showJsonSchemaDialog = {
      type: "tabbed",

      title: `Edit ${getLabel(targetNode)} Payload`,
      jsonSchemaParts: componentSchemas,
      dataByParts: (parts) => {
        return getFormValuesByPayloads(parts, targetNode);
      },

      onSubmit: data => {
        for (const schemaPartInfo of data) {
          setFormValuesToPayload(schemaPartInfo.schemaParts, node, schemaPartInfo.value);
        }

        NodeRepository.updateDbNode({
          id: targetNode.id,
          nodeConfig: targetNode.nodeConfig
        });

      }
    };
  }

  async function getTemplateData (): Promise<PayloadContext> {
    if (nodeProps.dynamicSourceMode === "payloadFields") {
      return {
        entries: nodeProps.dynamicData ?? [],
        shortName: "NONE",
        typeOfSource: "NODE_PAYLOAD"
      };
    } else {
      const globalDataSourceEntry = await DataSourceRepository.getSourceByShort(nodeProps.globalDataSource);

      switch (globalDataSourceEntry.config.type) {
        case "BY_CODE":
          // TODO use workers and other fancy stuff
          return {
            entries: JSON.parse(globalDataSourceEntry.config.code),
            shortName: nodeProps.globalDataSource,
            typeOfSource: "DATA_SOURCE"
          };
        default:
          return {
            entries: [],
            shortName: nodeProps.globalDataSource,
            typeOfSource: "DATA_SOURCE"
          };
      }
    }
  }

  const templateRootNodeId = $derived( nodeProps.layout.id);

  const cachedQueryResult = $derived.by(() => !!templateRootNodeId ? getCachedByIdNodeQuery(templateRootNodeId) : null);

  const mappedToLayoutNode = $derived.by(() => cachedQueryResult ?  convertDbNodeToDynamicLayoutNode(cachedQueryResult.rows[0]) : null);

</script>

{#if inEditMode}
  {#if label}
    {label}: {nodeProps.dynamicSourceMode} {nodeProps.globalDataSource}
    {#if nodeProps.dynamicSourceMode === "payloadFields"}
      <Button onclick={editTemplateEntries}>Edit Payloads ({nodeProps.dynamicData?.length})</Button>
    {/if}
    <br />
  {/if}

  {@const newLayoutContext = new LayoutContext({
    ...layoutContext.nodeInformations,
    root: node,
    node: layoutContext.node,
  }, layoutContext.render, {
    ...layoutContext.sharedAdditionalContext ?? {},
    isTemplateMode: true
  })}

  {#if mappedToLayoutNode}
    {@render newLayoutContext.render.renderChildNode(newLayoutContext.subNode(mappedToLayoutNode))}
  {:else}
    No template node yet
  {/if}
{:else}
  {@const dynamicDataPromise = getTemplateData()}

  {#if label}
    {label}: <br />
  {/if}

  {#await dynamicDataPromise}
    Loading template data
  {:then payloadContext}
    {#if !Array.isArray(payloadContext.entries)}
      Template Data must be an array: {JSON.stringify(payloadContext.entries)}
    {:else if payloadContext.entries.length > 0}
      <DynamicNodeLayout layoutContext={layoutContext} nodeId={nodeProps.layout.id} {payloadContext} />
    {:else}
      No template data
      {JSON.stringify(payloadContext)} <br />
      {JSON.stringify(nodeProps)}
    {/if}
  {/await}
{/if}
