<script lang="ts" module>
  import type { JsonSchemaParts, SchemaPartsGenerator } from "../jsonSchemaTypes";
  import { hasTitleSchema } from "../shared-schemas/title-schema";
  import {
    type DynamicLayoutNode,
    type DynamicLayoutNodeInfo, getLabel, setLabel
  } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { canHaveChildrenSchema } from "../shared-schemas/children-schemas";


  export function hasLucideIconSchema (): JsonSchemaParts {
    return {
      dataTab: "general",
      schemaProperties: {
        icon: {
          type: "string",
          title: "Icon",
          description: "This is using lucide icons, visit https://lucide.dev/icons/ and pick an icon you like"
        }
      },
      uiSchemaProperties: {
        icon: {
          "ui:options": {
            input: {
              autocomplete: "off"
            }
          }
        }
      },
      requiredProperties: ["icon"],
      getFormValuesByNode: (node: DynamicLayoutNode) => {
        return {
          icon: node.nodeConfig.icon ?? "LayoutDashboard"
        };
      },
      setToNode: (node: DynamicLayoutNode, values: any) => {
        node.nodeConfig.icon = values.icon;
        // console.info('setLabel', values.label, node);
      }
    };
  };


  export const SCHEMA_PARTS: SchemaPartsGenerator = (context) => [
    hasTitleSchema(true),
    canHaveChildrenSchema,
    hasLucideIconSchema
  ];

  export const DashboardPageNodeInfo: DynamicLayoutNodeInfo = {
    nodeType: "dashboard",
    schemaParts: SCHEMA_PARTS
  };
</script>

<script lang="ts">
  import type { ComponentProps } from "$lib/components/composites/dynamic-layout";

  let {
    layoutContext
  }: ComponentProps = $props();
</script>

{@render layoutContext.render.renderChildren(layoutContext)}
