<script lang="ts" module>
  import type { DynamicLayoutNodeInfo } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { TimerIcon } from "@lucide/svelte";

  export const TimerNodeInfo: DynamicLayoutNodeInfo = {
    nodeType: "timer",
    schemaParts: () => [],
    iconComponent: TimerIcon
  };
</script>

<script lang="ts">
  import { onMount } from 'svelte';
  import { Button } from '$lib/components/ui/button';
  import { type ComponentProps } from '$lib/components/composites/dynamic-layout';

  let {
    layoutContext
  }: ComponentProps = $props();

  let isRunning = $state(false);
  let isPomodoro = $state(false);
  let time = $state(0);
  let interval;

  function startTimer() {
    if (!isRunning) {
      isRunning = true;
      interval = setInterval(() => {
        time += 1;
      }, 1000);
    }
  }

  function stopTimer() {
    if (isRunning) {
      isRunning = false;
      clearInterval(interval);
    }
  }

  function resetTimer() {
    stopTimer();
    time = 0;
  }

  function togglePomodoro() {
    isPomodoro = !isPomodoro;
    resetTimer();
  }

  onMount(() => {
    return () => {
      clearInterval(interval);
    };
  });
</script>

<div>
  <Button onclick={startTimer} disabled={isRunning}>Start</Button>
  <Button onclick={stopTimer} disabled={!isRunning}>Stop</Button>
  <Button onclick={resetTimer}>Reset</Button>
  <Button onclick={togglePomodoro}>
    {isPomodoro ? 'Switch to Normal Timer' : 'Switch to Pomodoro Timer'}
  </Button>
  <div>
    {#if isPomodoro}
      <p>Pomodoro Timer: {Math.floor(time / 60)}:{time % 60}</p>
    {:else}
      <p>Normal Timer: {Math.floor(time / 60)}:{time % 60}</p>
    {/if}
  </div>
</div>
