import type { Schema } from '@sjsf/form';

export function dependableBooleanProperty(
	schemaDef: Required<Schema['properties']>,
	onFalse: Required<Schema['properties']>,
	onTrue: Required<Schema['properties']>,
	onTrueDeps?: Schema['dependencies']
): {
	property: Schema['properties'];
	dependencyEntry: Schema['dependencies'];
} {
	const theKey = Object.keys(schemaDef ?? {})[0];

	return {
		property: schemaDef,
		dependencyEntry: {
			[theKey]: {
				oneOf: [
					{
						properties: {
							[theKey]: {
								enum: [false]
							},
							...onFalse
						}
					},
					{
						properties: {
							[theKey]: {
								enum: [true]
							},
							...onTrue
						},

						dependencies: onTrueDeps
					}
				]
			}
		}
	};
}

export function dependableEnumProperty(
	schemaDef: NonNullable<Schema['properties']>,
	on: { [key: string]: Required<Schema['properties']> }
): {
	property: Schema['properties'];
	dependencyEntry: Schema['dependencies'];
} {
	const theKey = Object.keys(schemaDef ?? {})[0];

	const enums = Object.keys(on);

	return {
		property: schemaDef,
		dependencyEntry: {
			[theKey]: {
				oneOf: enums.map((key) => ({
					properties: {
						[theKey]: {
							enum: [key]
						},
						...on[key]
					}
				}))
			}
		}
	};
}


