<script lang="ts" module>
  import type { JsonSchemaParts, SchemaPartsGenerator } from "./jsonSchemaTypes";
  import type {
    DynamicLayoutNode,
    DynamicLayoutNodeInfo
  } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { CalendarDays } from "@lucide/svelte";

  interface DayNodeProps {
    colors: {
      dayNumberColor: string;
      dayAbbreviationColor: string;
      weekNumberColor: string;
      monthNameColor: string;
      yearColor: string;
    };
    visibility: {
      showDayNumber: boolean;
      showDayAbbreviation: boolean;
      showWeekNumber: boolean;
      showMonthName: boolean;
      showYear: boolean;
    };
  }

  const hasDayNodeSchema = (): JsonSchemaParts => {
    return {
      dataTab: "general",
      schemaProperties: {
        colors: {
          type: "object",
          properties: {
            dayNumberColor: {
              type: "string",
              title: "Day Number Color"
            },
            dayAbbreviationColor: {
              type: "string",
              title: "Day Abbreviation Color"
            },
            weekNumberColor: {
              type: "string",
              title: "Week Number Color"
            },
            monthNameColor: {
              type: "string",
              title: "Month Name Color"
            },
            yearColor: {
              type: "string",
              title: "Year Color"
            }
          },
          required: ["dayNumberColor", "dayAbbreviationColor", "weekNumberColor", "monthNameColor", "yearColor"]
        },
        visibility: {
          type: "object",
          properties: {
            showDayNumber: {
              type: "boolean",
              title: "Show Day Number"
            },
            showDayAbbreviation: {
              type: "boolean",
              title: "Show Day Abbreviation"
            },
            showWeekNumber: {
              type: "boolean",
              title: "Show Week Number"
            },
            showMonthName: {
              type: "boolean",
              title: "Show Month Name"
            },
            showYear: {
              type: "boolean",
              title: "Show Year"
            }
          }
        }
      },
      requiredProperties: [],
      uiSchemaProperties: {},
      getFormValuesByNode: (node: DynamicLayoutNode) => {
        const nodeProps = node.nodeConfig as DayNodeProps;
        return {
          colors: {
            dayNumberColor: nodeProps?.colors?.dayNumberColor ?? "#FF5733",
            dayAbbreviationColor: nodeProps?.colors?.dayAbbreviationColor ?? "#33FF57",
            weekNumberColor: nodeProps?.colors?.weekNumberColor ?? "#3357FF",
            monthNameColor: nodeProps?.colors?.monthNameColor ?? "#FF33A1",
            yearColor: nodeProps?.colors?.yearColor ?? "#FFD700"
          },
          visibility: {
            showDayNumber: nodeProps?.visibility?.showDayNumber ?? true,
            showDayAbbreviation: nodeProps?.visibility?.showDayAbbreviation ?? true,
            showWeekNumber: nodeProps?.visibility?.showWeekNumber ?? true,
            showMonthName: nodeProps?.visibility?.showMonthName ?? true,
            showYear: nodeProps?.visibility?.showYear ?? true
          }
        };
      },
      setToNode: (node: DynamicLayoutNode, values: any) => {
        node.nodeConfig.colors = values.colors;
        node.nodeConfig.visibility = values.visibility;
      }
    };
  };

  export const SCHEMA_PARTS: SchemaPartsGenerator = (context) => [
    hasDayNodeSchema
  ];

  export const DayNodeInfo: DynamicLayoutNodeInfo = {
    nodeType: "day",
    schemaParts: SCHEMA_PARTS,
    iconComponent: CalendarDays
  };
</script>

<script lang="ts">
  import { type ComponentProps } from "$lib/components/composites/dynamic-layout";
  import { onMount } from "svelte";

  let {
    layoutContext
  }: ComponentProps = $props();

  let node = $derived(layoutContext.node);
  let nodeProps = $derived(node.nodeConfig as DayNodeProps);

  let colors = $derived(nodeProps?.colors ?? {
    dayNumberColor: "#FF5733",
    dayAbbreviationColor: "#33FF57",
    weekNumberColor: "#3357FF",
    monthNameColor: "#FF33A1",
    yearColor: "#FFD700"
  });

  let visibility = $derived(nodeProps?.visibility ?? {
    showDayNumber: true,
    showDayAbbreviation: true,
    showWeekNumber: true,
    showMonthName: true,
    showYear: true
  });

  let currentDate = $state(new Date());

  onMount(() => {
    const interval = setInterval(() => {
      currentDate = new Date();
    }, 1000);
    return () => clearInterval(interval);
  });

  function getWeekNumber(date: Date) {
    const firstDayOfYear = new Date(date.getFullYear(), 0, 1);
    const pastDaysOfYear = (date.getTime() - firstDayOfYear.getTime()) / 86400000;
    return Math.ceil((pastDaysOfYear + firstDayOfYear.getDay() + 1) / 7);
  }
</script>

<style>
  .day-node {
    display: flex;
    flex-direction: column;
    align-items: center;
  }

  .day-number {
    font-size: 2rem;
    color: var(--day-number-color);
  }

  .day-abbreviation {
    font-size: 1.5rem;
    color: var(--day-abbreviation-color);
  }

  .week-number {
    font-size: 1rem;
    color: var(--week-number-color);
  }

  .month-name {
    font-size: 1rem;
    color: var(--month-name-color);
  }

  .year {
    font-size: 1rem;
    color: var(--year-color);
  }
</style>

<div class="day-node">
  {#if visibility.showDayNumber}
    <div class="day-number" style="--day-number-color: {colors.dayNumberColor};">
      {currentDate.getDate()}
    </div>
  {/if}
  {#if visibility.showDayAbbreviation}
    <div class="day-abbreviation" style="--day-abbreviation-color: {colors.dayAbbreviationColor};">
      {currentDate.toLocaleString('default', { weekday: 'short' })}
    </div>
  {/if}
  {#if visibility.showWeekNumber}
    <div class="week-number" style="--week-number-color: {colors.weekNumberColor};">
      Week {getWeekNumber(currentDate)}
    </div>
  {/if}
  {#if visibility.showMonthName}
    <div class="month-name" style="--month-name-color: {colors.monthNameColor};">
      {currentDate.toLocaleString('default', { month: 'long' })}
    </div>
  {/if}
  {#if visibility.showYear}
    <div class="year" style="--year-color: {colors.yearColor};">
      {currentDate.getFullYear()}
    </div>
  {/if}
</div>
