export function lazyAsyncState<T>(lazyCallback: () => Promise<T>) {
	let cachedState = $state<T | null>(null);

	let triggeredCache = false;

	const saveCallbackToState = () =>
		lazyCallback().then((value) => {
			cachedState = value;
		});

	return {
		get value() {
      if (!triggeredCache) {
				triggeredCache = true;

      	// trigger the lazy load once
				void saveCallbackToState();
			}

			return cachedState;
		}
	};
}
