import type {
	ChildrenViewMode,
	DashboardLayoutNode,
} from "../dynamic-layout-app-types/dynamic-layout-types";
import { getGridNodeOptions } from './gridUtils';

export function getChildrenViewModeProps(node?: DashboardLayoutNode): Partial<ChildrenViewMode> {
	return node?.nodeConfig as ChildrenViewMode ?? { type: 'rows' };
}

export function childrenViewModePanel(node: DashboardLayoutNode, children: DashboardLayoutNode[] = []) {
	const styleParts: string[] = [];

	const childrenViewMode = getChildrenViewModeProps(node);

	switch (childrenViewMode?.type) {
		case 'rows':
			styleParts.push('display: flex; flex-direction: column; flex-wrap: wrap; gap: 0.25rem;');
			break;
		case 'columns':
			styleParts.push('display: flex; flex-direction: row; flex-wrap: wrap; gap: 0.25rem;');
			break;
		case 'grid':
			const childrenOptions = children.map((child) => getGridNodeOptions(child)).filter(Boolean);

			let maxCol = Math.max(...childrenOptions.map((t) => t.col));
			let maxRow = Math.max(...childrenOptions.map((t) => t.row));

			styleParts.push('display: grid;');
			styleParts.push(` grid-template-columns: repeat(${maxCol}, minmax(0, 1fr))`);

			break;
		case 'custom':
			styleParts.push(childrenViewMode.panelStyle ?? '');
			break;
	}

	styleParts.push(node.layoutData?.elementProps?.styleCss ?? '');

	return styleParts.join(';');
}

export function childrenViewModeItem(
	parentConfig: Partial<DashboardLayoutNode> | undefined,
	childNode: DashboardLayoutNode
) {
	const styleParts: string[] = [];

	const childrenViewMode = getChildrenViewModeProps(parentConfig as DashboardLayoutNode);

	switch (childrenViewMode?.type) {
		case 'grid':
			const childOptions = getGridNodeOptions(childNode);
			const gridStyles = {
				gridColumnStart: childOptions.col,
				gridColumnEnd: childOptions.col + childOptions.colSpan,
				gridRowStart: childOptions.row,
				gridRowEnd: childOptions.row + childOptions.rowSpan
			};
			const gridRowStyle = `${gridStyles.gridRowStart} / ${gridStyles.gridRowEnd}`;
			const gridColStyle = `${gridStyles.gridColumnStart} /  ${gridStyles.gridColumnEnd}`;

			styleParts.push(`grid-column: ${gridColStyle}; grid-row: ${gridRowStyle};position: relative`);
			break;

		case 'columns':
			styleParts.push('flex: 1;');
			break

		case 'custom':
			styleParts.push(childrenViewMode.itemStyle ?? '');
			break;
	}

	styleParts.push(childNode.layoutData?.elementProps?.styleCss ?? '');

	return styleParts.join(';');
}
