import { LayoutContext } from "$lib/components/composites/dynamic-layout";
import { NodeRepository } from "./nodeRepository.svelte";
import { convertDbNodeToDynamicLayoutNode } from "./layoutDbNodeConverter";
import { type InsertableNode, type NodeId } from "./evolu/datastructure";
import type {
  DashboardLayoutNode,
  DynamicLayoutNode
} from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
import type {
  INodePersistenceContext,
  InsertableNodeEditableFields
} from "$lib/contexts/contextTypes";
import { ensurePath } from "$lib/blocks/data-utils/ensurePath";
import { NodeDataRepository } from "./nodeDataRepository.svelte";

// TODO merge NodePersistence / NodeRepository or split their responsibilities
export const NodePersistence: INodePersistenceContext = {
  async getOrCreateRootNode () {
    const rootNode = await NodeRepository.getRootNode();

    let rootId = rootNode?.id;

    if (!rootNode) {
      const createdRootNodeId = await NodeRepository.addDbNode({
        type: "children",
        specialFlags: {
          isRootNode: true
        },
        layoutData: {},
        nodeConfig: {},
        ofTemplate: false,
        order: 1
      });

      // console.info("createdRootNode", createdRootNodeId);

      rootId = createdRootNodeId;
    }

    const dbNode = await NodeRepository.getNodeAsync(rootId);

    return convertDbNodeToDynamicLayoutNode(dbNode);
  },

  async addDbNode (
    rootType: string,
    parentNodeId: string,
    applyChangesCallback: (node: InsertableNode) => void
  ) {
    const newNode: InsertableNode = {
      type: "div",
      layoutData: {},
      nodeConfig: {},
      ofTemplate: rootType === "dynamic",
      parentId: parentNodeId,
      order: 0
    };

    applyChangesCallback(newNode);

    const createdNodeId = await NodeRepository.addDbNode(newNode);

    return convertDbNodeToDynamicLayoutNode(await NodeRepository.getNodeAsync(createdNodeId));
  },

  async addNode (
    rootType: string,
    parentNodeId: string|null,
    applyChangesCallback: (node: InsertableNodeEditableFields) => void
  ) {
    const newNode: InsertableNodeEditableFields = {
      type: "div",
      layoutData: {},
      nodeConfig: {},
      order: 0
    };

    applyChangesCallback(newNode);

    const createdNodeId = await NodeRepository.addDbNode({
      ...newNode,
      ofTemplate: rootType === "dynamic",
      parentId: parentNodeId
    });

    if (newNode.type === "dynamic") {
      const createdSubNode = await NodePersistence.addNode(
        "dynamic",
        createdNodeId,
        (nodeInState) => {
          nodeInState.type = "children";
        }
      );

      NodeRepository.updateDbNode({
        id: createdNodeId,
        nodeConfig: {
          ...newNode.nodeConfig,
          layout: {
            id: createdSubNode.id,
            type: "children"
          }
        }
      });
    }

    return convertDbNodeToDynamicLayoutNode(await NodeRepository.getNodeAsync(createdNodeId));
  },

  async applyChangesToNode (
    layoutContext: LayoutContext,
    nodeId: string,
    applyChangesCallback: (node: DynamicLayoutNode) => void
  ) {
    const nodeInState = convertDbNodeToDynamicLayoutNode(
      await NodeRepository.getNodeAsync(nodeId as NodeId)
    );

    if (!nodeInState) {
      alert("could not find the node in the state!");
      return;
    }

    applyChangesCallback(nodeInState);

    NodeRepository.updateNode(layoutContext.nodeInformations.root.type === "dynamic", nodeInState);
  },

  async applyLayoutData (
    layoutContext: LayoutContext,
    nodeId: string,
    applyChangesCallback: (nodeProps: Partial<DashboardLayoutNode["layoutData"]>) => void
  ) {
    const nodeInState = convertDbNodeToDynamicLayoutNode(
      await NodeRepository.getNodeAsync(nodeId as NodeId)
    );

    if (!nodeInState) {
      alert("could not find the node in the state!");
      return;
    }

    ensurePath(nodeInState, "layoutData");

    applyChangesCallback(nodeInState.layoutData);

    // TODO apply only the changed not the full object

    NodeRepository.updateNode(layoutContext.nodeInformations.root.type === "dynamic", nodeInState);
  },

  async applyNodeConfig (
    layoutContext: LayoutContext,
    nodeId: string,
    applyChangesCallback: (nodeProps: DynamicLayoutNode["nodeConfig"]) => void
  ) {
    const nodeInState = convertDbNodeToDynamicLayoutNode(
      await NodeRepository.getNodeAsync(nodeId as NodeId)
    );

    if (!nodeInState) {
      alert("could not find the node in the state!");
      return;
    }

    ensurePath(nodeInState, "nodeConfig");

    applyChangesCallback(nodeInState.nodeConfig);

    NodeRepository.updateNode(layoutContext.nodeInformations.root.type === "dynamic", nodeInState);
  },

  async deleteNode (nodeId: NodeId) {
    const children = await NodeRepository.getNodesAsync(nodeId);

    NodeRepository.deleteNode(nodeId);
    await NodeDataRepository.deleteNodeDataByNodeId(nodeId);

    for (const child of children) {
      await this.deleteNode(child.id);
    }

  },
  /*
    async exportNodes() {
      return await NodeRepository.exportNodes();
    },
  
    importNodes(jsonString: string): void {
      NodeRepository.importNodes(jsonString);
    },
  */
  async changeParentNode (layoutContext: LayoutContext, nodeId: string, newParentId: string) {
    const nodeInState = await NodeRepository.getNodeAsync(nodeId as NodeId);
    const newParentNode = await NodeRepository.getNodeAsync(newParentId as NodeId);

    if (!nodeInState || !newParentNode) {
      alert("could not find the node or the new parent in the state!");
      return;
    }

    NodeRepository.updateDbNode({
      id: nodeId,
      parentId: newParentId
    });
  }
};
