<script lang="ts" module>
  import type { JsonSchemaParts, SchemaPartsGenerator } from "./jsonSchemaTypes";
  import type {
    DynamicLayoutNode,
    DynamicLayoutNodeInfo
  } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { Code } from "@lucide/svelte";

  export interface TextNodeProps {
    contentType: "html" | "markdown";
    content: string;
  }

  const hasTextContentSchema = (): JsonSchemaParts => {
    return {
      dataTab: "general",
      schemaProperties: {
        contentType: {
          type: "string",
          enum: ["html", "markdown"],
          title: "Content Type"
        },
        content: {
          type: "string",
          title: "Content"
        }
      },
      requiredProperties: ["contentType", "content"],
      uiSchemaProperties: {
        content: {
          "ui:widget": "textarea",
          "ui:options": {
            input: {
              autocomplete: "off",
              rows: 15
            }
          }
        }
      },
      getFormValuesByNode: (node: DynamicLayoutNode) => {
        const nodeProps = node.nodeConfig as TextNodeProps;
        return {
          contentType: nodeProps.contentType ?? "html",
          content: nodeProps.content ?? ""
        };
      },
      setToNode: (node: DynamicLayoutNode, values: any) => {
        node.nodeConfig.contentType = values.contentType;
        node.nodeConfig.content = values.content;
      }
    };
  };

  export const SCHEMA_PARTS: SchemaPartsGenerator = (context) => [
    hasTextContentSchema
  ];

  export const TextNodeInfo: DynamicLayoutNodeInfo = {
    nodeType: "text",
    schemaParts: SCHEMA_PARTS,
    iconComponent: Code
  };
</script>

<script lang="ts">
  import { type ComponentProps } from "$lib/components/composites/dynamic-layout";
  import { marked } from "marked";

  let {
    layoutContext
  }: ComponentProps = $props();

  let node = $derived(layoutContext.node);
  let nodeProps = $derived(node.nodeConfig as TextNodeProps);

  let content = $derived(nodeProps.content ?? "");
  let contentType = $derived(nodeProps.contentType ?? "html");

  const renderer = new marked.Renderer();
  renderer.link = function({ href, title, text }) {
    return `<a target="_blank" href="${href}">${text}` + "</a>";
  };
  let renderedContent = $derived(contentType === "markdown" ? marked(content, {
    renderer
  }) : content);
</script>

<div class="text-node" class:markdown-body={contentType === "markdown"}>
  {@html renderedContent}
</div>
