import type { JsonSchemaParts } from '../jsonSchemaTypes';
import type { CanAddChildrenAtRuntimeNodeProps } from '../../../dynamic_layout_test/KnownNodeProps';
import { ensurePath } from '$lib/blocks/data-utils/ensurePath';
import { dependableEnumProperty } from '$lib/blocks/svelte-jsonschema-form/schema-utils';
import type { JSONSchema7Definition } from 'json-schema';
import { NodeRepository } from '$lib/database/nodeRepository.svelte.js';
import type { NodeId } from '$lib/database/evolu/datastructure';
import { convertDbNodeToDynamicLayoutNode } from '$lib/database/layoutDbNodeConverter';
import {
	type ChildrenViewMode,
	type DynamicLayoutNode,
	getLabel,
	setLabel
} from '$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types';

export const canAddChildrenAtRuntime = (): JsonSchemaParts => {
	return {
		dataTab: 'general',
		schemaProperties: {
			canAddChildrenAtRuntime: {
				type: 'boolean',
				title: 'Can Add Children At Runtime'
			}
		},
		uiSchemaProperties: {},
		requiredProperties: [],
		getFormValuesByNode: (node: DynamicLayoutNode) => {
			const can = node.nodeConfig as CanAddChildrenAtRuntimeNodeProps;

			return { canAddChildrenAtRuntime: can?.addChildrenAtRuntime ?? false };
		},
		setToNode: (node: DynamicLayoutNode, values: any) => {
			ensurePath(node, 'nodeConfig');

			const can = node.nodeConfig as CanAddChildrenAtRuntimeNodeProps;
			can.addChildrenAtRuntime = values.canAddChildrenAtRuntime;
		}
	};
};

export const hasNamedChildrenNodes = (targetSubType: string) => () => {
	return {
		dataTab: 'general',
		schemaProperties: {
			children: {
				type: 'array',
				title: 'Children',
				items: {
					type: 'object',
					properties: {
						label: {
							type: 'string',
							title: 'Label'
						},
						id: {
							type: 'string',
							title: 'Id'
						}
					},
					required: ['label']
				}
			}
		},
		uiSchemaProperties: {
			children: {
				items: {
					id: {
						'ui:field': 'hidden'
					},
					'ui:options': {
						title: ''
					}
				}
			}
		},
		requiredProperties: [],
		getFormValuesByNode: async (node: DynamicLayoutNode) => {
			const dbNodes = node.id ? await NodeRepository.getNodesAsync(node.id as NodeId) : [];

			const nodes = dbNodes.map((child) => convertDbNodeToDynamicLayoutNode(child));

			return {
				children:
					nodes?.map((child) => ({
						label: getLabel(child),
						id: child.id
					})) ?? []
			};
		},
		setToNode: async (node: DynamicLayoutNode, values: any) => {
			const dbNodes = node.id ? await NodeRepository.getNodesAsync(node.id as NodeId) : [];

			const nodes = dbNodes.map((child) => convertDbNodeToDynamicLayoutNode(child));

			for (let child of values.children) {
				const existingChild = nodes!.find((c) => c.id === child.id);
				if (existingChild) {
					console.info({
						existingChild: existingChild
					});
					if (existingChild.layoutData) {
						setLabel(existingChild, child.label);

						NodeRepository.updateDbNode({
							id: existingChild.id,
							layoutData: existingChild.layoutData
						});
					}
				} else {
					NodeRepository.addDbNode({
						type: targetSubType,
						ofTemplate: false,
						order: 0,
						parentId: node.id,
						layoutData: {
							label: child.label
							// [DYNAMIC_LAYOUT_PROPS.LABEL]: child.label
						}
					});
				}
			}

			// remove deleted children
			for (let child of nodes!) {
				if (!values.children.find((c) => c.id === child.id)) {
					NodeRepository.deleteNode(child.id);
				}
			}
		}
	} satisfies JsonSchemaParts;
};

export const canHaveChildrenSchema = () => {
	const styleSelection = dependableEnumProperty(
		{
			type: {
				type: 'string',
				enum: ['rows', 'columns', 'grid', 'custom'],
				title: 'Children View Mode'
			}
		},
		{
			rows: {
				helpText: {
					title: '',
					description: 'Children will be displayed in a list vertically.',
					type: 'null'
				}
			},
			columns: {
				helpText: {
					title: '',
					description: 'Children will be displayed in a list horizontally.',
					type: 'null'
				}
			},
			grid: {
				helpText: {
					title: '',
					description:
						'Children will be displayed in a grid. Each child will get a grid config property',
					type: 'null'
				}
			},
			custom: {
				panelStyle: {
					type: 'string',
					title: 'Panel Style'
				},
				itemStyle: {
					type: 'string',
					title: 'Item Style'
				}
			}
		}
	);

	return {
		dataTab: 'general',
		schemaProperties: {
			childrenViewMode: {
				type: 'object',
				title: 'Children View Mode',
				properties: {
					...styleSelection.property
				},

				dependencies: {
					...styleSelection.dependencyEntry
				}
			} satisfies JSONSchema7Definition
		},
		uiSchemaProperties: {
			childrenViewMode: {
				panelStyle: {
					'ui:widget': 'textarea',
					'ui:options': {
						input: {
							autocomplete: 'off',
							rows: 5
						}
					}
				},
				itemStyle: {
					'ui:widget': 'textarea',
					'ui:options': {
						input: {
							autocomplete: 'off',
							rows: 5
						}
					}
				}
			}
		},
		requiredProperties: [],
		getFormValuesByNode: (node: DynamicLayoutNode) => {
			const childrenMode = node.nodeConfig as ChildrenViewMode;

			return {
				childrenViewMode: {
					type: childrenMode?.type ?? 'rows',
					panelStyle: childrenMode?.panelStyle ?? '',
					itemStyle: childrenMode?.itemStyle ?? ''
				}
			};
		},
		setToNode: (node: DynamicLayoutNode, values: any) => {
			ensurePath(node, 'nodeConfig');

			const childrenViewModeProps = node.nodeConfig as ChildrenViewMode;

			childrenViewModeProps.type = values.childrenViewMode.type;
			childrenViewModeProps.panelStyle = values.childrenViewMode.panelStyle;
			childrenViewModeProps.itemStyle = values.childrenViewMode.itemStyle;
		}
	} satisfies JsonSchemaParts;
};

export function nodeCanHoldChildren(node?: DynamicLayoutNode): boolean {
	return ['tab', 'children', 'collapsible'].includes(node?.type ?? '');
}
