import { SvelteMap, SvelteSet } from "svelte/reactivity";

export const LiveNodeDataState = new SvelteMap();

export function getLiveNodeDataStateForName<T> (name: string, startingValue: T) {
  let state = $state(startingValue);

  $effect(() => {
    if (name !== "" && name !== undefined) {
      LiveNodeDataState.set(name, state);
    }
  });

  return {
    get current () {
      return state;
    },
    set current (value: T) {
      state = value;
    }
  };
}

export function getKeyedLiveNodeDataStateForName<T> (name: string, subKey: string, startingValue: T) {
  let state = $state(startingValue);

  LiveNodeDataState.set(name, LiveNodeDataState.get(name) || {});

  return {
    get current () {
      return state;
    },
    set current (value: T) {
      state = value;

      if (name !== "" && name !== undefined) {
        LiveNodeDataState.set(name, {
          ...(LiveNodeDataState.get(name) || {}),
          [subKey]: state
        });
      }
    }
  };
}
