<script lang="ts" module>
  import type { JsonSchemaParts, SchemaPartsGenerator } from "./jsonSchemaTypes";
  import { ensurePath } from "$lib/blocks/data-utils/ensurePath";
  import type { DynamicLayoutNode, DynamicLayoutNodeInfo } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { CalendarIcon } from "@lucide/svelte";

  export interface DeadlineNodeProps {
    targetDate: string;
    showSeconds: boolean;
    showMinutes: boolean;
    showHours: boolean;
    mode: "none" | "negative" | "positive";
  }

  const hasTargetDateSchema = (): JsonSchemaParts => {
    return {
      dataTab: "general",
      schemaProperties: {
        targetDate: {
          type: "string",
          format: "date",
          title: "Target Date"
        },
        showSeconds: {
          type: "boolean",
          title: "Show Seconds"
        },
        showMinutes: {
          type: "boolean",
          title: "Show Minutes"
        },
        showHours: {
          type: "boolean",
          title: "Show Hours"
        },
        mode: {
          type: "string",
          enum: ["none", "negative", "positive"],
          title: "Mode"
        }
      },
      requiredProperties: ["targetDate"],
      uiSchemaProperties: {},
      getFormValuesByNode: (node: DynamicLayoutNode) => {
        const nodeProps = node.nodeConfig as DeadlineNodeProps;
        return {
          // default should be today in YYYY-MM-DD format

          targetDate: nodeProps?.targetDate ?? new Date().toISOString().split('T')[0],
          showSeconds: nodeProps?.showSeconds ?? true,
          showMinutes: nodeProps?.showMinutes ?? true,
          showHours: nodeProps?.showHours ?? true,
          mode: nodeProps?.mode ?? "none"
        };
      },
      setToNode: (node: DynamicLayoutNode, values: any) => {
        	ensurePath(node, 'nodeConfig');
        node.nodeConfig.targetDate = values.targetDate;
        node.nodeConfig.showSeconds = values.showSeconds;
        node.nodeConfig.showMinutes = values.showMinutes;
        node.nodeConfig.showHours = values.showHours;
        node.nodeConfig.mode = values.mode;
      }
    };
  };

  export const SCHEMA_PARTS: SchemaPartsGenerator = (context) => [
    hasTargetDateSchema
  ];

  export const DeadlineNodeInfo: DynamicLayoutNodeInfo = {
    nodeType: "deadline",
    schemaParts: SCHEMA_PARTS,
    iconComponent: CalendarIcon
  };
</script>

<script lang="ts">
  import { onMount } from "svelte";
  import { type ComponentProps } from "$lib/components/composites/dynamic-layout";
  import { PencilIcon } from "@lucide/svelte";
  import { dialogState } from "../../dialogs/dialog-state.svelte.js";
  import { getFormValuesByPayloads } from "./jsonSchemaCombinators";
  import { NodePersistenceContext } from "../../contexts/nodePersistence.context";

  let {
    layoutContext
  }: ComponentProps = $props();

  let node = $derived(layoutContext.node);

  const nodePersistenceContext = NodePersistenceContext.get();

  let nodeProps = $derived(layoutContext.getNodeConfig<DeadlineNodeProps>());

  let targetDate = $derived(nodeProps?.targetDate);
  let showSeconds = $derived(nodeProps?.showSeconds);
  let showMinutes = $derived(nodeProps?.showMinutes);
  let showHours = $derived(nodeProps?.showHours);
  let mode = $derived(nodeProps?.mode);

  let remainingTime = $state({
    days: 0,
    hours: 0,
    minutes: 0,
    seconds: 0
  });

  let bottomLineColor = $state("transparent");

  function calculateRemainingTime () {
    const now = new Date().getTime();
    const target = new Date(targetDate).getTime();
    const distance = target - now;

    if (distance < 0) {
      remainingTime = {
        days: 0,
        hours: 0,
        minutes: 0,
        seconds: 0
      };
      bottomLineColor = "transparent";
      return;
    }

    const days = Math.floor(distance / (1000 * 60 * 60 * 24));
    const hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
    const minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((distance % (1000 * 60)) / 1000);

    remainingTime = {
      days,
      hours,
      minutes,
      seconds
    };

    if (mode === "negative") {
      if (days > 7) {
        bottomLineColor = "green";
      } else if (days <= 7 && days > 2) {
        bottomLineColor = "yellow";
      } else {
        bottomLineColor = "red";
      }
    } else if (mode === "positive") {
      if (days > 7) {
        bottomLineColor = "orange";
      } else if (days <= 7 && days > 2) {
        bottomLineColor = "yellow";
      } else {
        bottomLineColor = "green";
      }
    } else {
      bottomLineColor = "transparent";
    }
  }

  onMount(() => {
    calculateRemainingTime();
    const interval = setInterval(calculateRemainingTime, 1000);
    return () => clearInterval(interval);
  });

  function showEditTargetDateModal () {
    dialogState.showJsonSchemaDialog = {
      title: "Edit Target Date",
      type: 'tabbed',

      jsonSchemaParts: SCHEMA_PARTS(layoutContext),

      dataByParts: parts => {
        return getFormValuesByPayloads(parts, node);
      },

      onSubmit: (values) => {
        nodePersistenceContext.applyNodeConfig(layoutContext, node.id, (nodeProps) => {
          // console.info('values', values);
          nodeProps.targetDate = values[0].value.targetDate;
          nodeProps.showSeconds = values[0].value.showSeconds;
          nodeProps.showMinutes = values[0].value.showMinutes;
          nodeProps.showHours = values[0].value.showHours;
          nodeProps.mode = values[0].value.mode;
        });

        calculateRemainingTime();
      }
    }
  }
</script>

<style>
   .deadline {
      font-family: Arial, sans-serif;
      text-align: center;
   }

   .time-part {
      display: inline-block;
      margin: 0 10px;
   }

   .label {
      font-weight: bold;
   }

   .bottom-line {
      height: 5px;
      width: 100%;
      background-color: var(--bottom-line-color);
      margin-top: 10px;
   }
</style>

<div class="deadline">
  {#if remainingTime.days > 0}
    <div class="time-part">
      <span class="label">Days:</span> {remainingTime.days}
    </div>
  {/if}
  {#if (remainingTime.hours > 0 || remainingTime.days > 0) && showHours}
    <div class="time-part">
      <span class="label">Hours:</span> {remainingTime.hours}
    </div>
  {/if}
  {#if (remainingTime.minutes > 0 || remainingTime.hours > 0 || remainingTime.days > 0) && showMinutes}
    <div class="time-part">
      <span class="label">Minutes:</span> {remainingTime.minutes}
    </div>
  {/if}
  {#if showSeconds}
    <div class="time-part">
      <span class="label">Seconds:</span> {remainingTime.seconds}
    </div>
  {/if}
  <div class="bottom-line" style="--bottom-line-color: {bottomLineColor};"></div>
</div>

<PencilIcon size="16" color="white" style="display: inline-block; "
            onclick={() => {showEditTargetDateModal()}} />
