<script lang="ts" module>
  import type { JsonSchemaParts, SchemaPartsGenerator } from "./jsonSchemaTypes";
  import { hasTitleSchema } from "./shared-schemas/title-schema";
  import type { DynamicLayoutNodeInfo } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { Image } from "@lucide/svelte";

  export interface XKCDNodeProps {
    type: "latest" | "random" | "specific";
    specificId?: number;
  }

  const hasXKCDSchema = (): JsonSchemaParts => {
    return {
      dataTab: "general",
      schemaProperties: {
        type: {
          type: "string",
          title: "Type",
          enum: ["latest", "random", "specific"]
        },
        specificId: {
          type: "number",
          title: "Specific ID",
          default: 1
        }
      },
      requiredProperties: ["type"],
      uiSchemaProperties: {

      },
      getFormValuesByNode: (node) => {
        const nodeProps = node.nodeConfig as XKCDNodeProps;
        return {
          type: nodeProps.type,
          specificId: nodeProps.specificId ?? 1
        };
      },
      setToNode: (node, values) => {
        node.nodeConfig.type = values.type;
        node.nodeConfig.specificId = values.specificId;
      }
    };
  };

  export const SCHEMA_PARTS: SchemaPartsGenerator = (context) => [
    hasTitleSchema(true),
    hasXKCDSchema
  ];

  export const XKCDNodeInfo: DynamicLayoutNodeInfo = {
    nodeGroup: "FUN",
    nodeType: "xkcd",
    schemaParts: SCHEMA_PARTS,
    iconComponent: Image
  };
</script>

<script lang="ts">
  import { type ComponentProps } from "$lib/components/composites/dynamic-layout";

  let {
    layoutContext
  }: ComponentProps = $props();

  let node = $derived(layoutContext.node);
  let nodeProps = $derived(node.nodeConfig as XKCDNodeProps);

  let type = $derived(nodeProps.type ?? "latest");
  let specificId = $derived(nodeProps.specificId ?? 1);

  let comicData = $state<{
    img: string;
    title: string;
    alt: string;
  } | null>(null);

  function corsFetch(url: string) {
    return fetch(`https://corsproxy.io/?url=${encodeURIComponent(url)}`).then(res => res.json());
  }

  function makeXHRRequest(url: string): Promise<any> {
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    const corsProxy = 'https://corsproxy.io/?url=';
    xhr.open('GET', corsProxy + encodeURIComponent(url), true);

    xhr.onload = function() {
      if (xhr.status === 200) {
        resolve(JSON.parse(xhr.responseText));
      } else {
        reject(new Error(`Request failed with status ${xhr.status}`));
      }
    };

    xhr.onerror = () => reject(new Error('Network error'));
    xhr.send();
  });
}

  async function fetchComic() {
    let url = "https://xkcd.com/info.0.json";
    if (type === "random") {
      const latestComic = await corsFetch("https://xkcd.com/info.0.json");
      const randomId = Math.floor(Math.random() * latestComic.num) + 1;
      url = `https://xkcd.com/${randomId}/info.0.json`;
    } else if (type === "specific") {
      url = `https://xkcd.com/${specificId}/info.0.json`;
    }

    const data = await corsFetch(url);
    comicData = {
      img: data.img,
      title: data.title,
      alt: data.alt
    };
  }

  $effect(() => {
    fetchComic();
  });
</script>

<style>
  .xkcd-comic {
    text-align: center;
  }

  .xkcd-comic img {
    max-width: 100%;
    height: auto;
  }

  .xkcd-comic h3 {
    margin: 0.5rem 0;
  }

  .xkcd-comic p {
    font-style: italic;
    color: #666;
  }
</style>

<div class="xkcd-comic">
  {#if comicData}
    <h3>{comicData.title}</h3>
    <img src={comicData.img} alt={comicData.alt} />
    <p>{comicData.alt}</p>
  {:else}
    <p>Loading XKCD comic...</p>
  {/if}
</div>
