<script lang="ts" module>
  import type { JsonSchemaParts, SchemaPartsGenerator } from "./jsonSchemaTypes";
  import type {
    DynamicLayoutNode,
    DynamicLayoutNodeInfo
  } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { Coins } from "@lucide/svelte";

  export interface CryptoCoinPriceNodeProps {
    coin: string;
  }

  const hasCoinSchema = (): JsonSchemaParts => {
    return {
      dataTab: "general",
      schemaProperties: {
        coin: {
          type: "string",
          title: "Coin"
        }
      },
      requiredProperties: ["coin"],
      uiSchemaProperties: {},
      getFormValuesByNode: (node: DynamicLayoutNode) => {
        const nodeProps = node.nodeConfig as CryptoCoinPriceNodeProps;
        return {
          coin: nodeProps.coin ?? "bitcoin"
        };
      },
      setToNode: (node: DynamicLayoutNode, values: any) => {
        node.nodeConfig.coin = values.coin;
      }
    };
  };

  export const SCHEMA_PARTS: SchemaPartsGenerator = (context) => [
    hasCoinSchema
  ];

  export const CryptoCoinPriceNodeInfo: DynamicLayoutNodeInfo = {
    nodeType: "crypto-coin-price",
    schemaParts: SCHEMA_PARTS,
    iconComponent: Coins
  };

  class CryptoCoinPriceWS {
    ws: WebSocket|undefined;
    listenerTimeout: ReturnType<typeof setTimeout>|undefined;
    listenerRunningForCoins: string[] = [];
    listeners: Record<string, (price: number) => void> = {};

    constructor() {
    }

    startListeningDebounced () {
      if (this.listenerTimeout) {
        clearTimeout(this.listenerTimeout);
      }

      this.listenerTimeout = setTimeout(() => {
        this.startListening();
      }, 1000);
    }

    startListening () {
      const coinNames = Object.keys(this.listeners);

      if (coinNames.length === 0 || coinNames.every(c => this.listenerRunningForCoins.includes(c))) {
        this.stopListening();
        return;
      }

      this.listenerRunningForCoins = coinNames;

      this.ws = new WebSocket(`wss://ws.coincap.io/prices?assets=${coinNames.join(",")}`);
      this.ws.onmessage = this.wsOnMessage.bind(this);
    }

    stopListening(){
      if (this.ws) {
        this.ws.close();
        this.ws.removeEventListener("message", this.wsOnMessage);
        this.ws = undefined;
      }
    }

    wsOnMessage(event: MessageEvent) {
      const data = JSON.parse(event.data);
      const coinNames = Object.keys(data);
      for (const coinName of coinNames) {
        this.handleCoinUpdate(coinName, data[coinName]);
      }
    }

    handleCoinUpdate(coin: string, price: number) {
      if (this.listeners[coin]) {
        this.listeners[coin](price);
      }
    }

    addListener(coinName: string, onPriceUpdate: (price: number) => void): () => void {
      this.listeners[coinName] = onPriceUpdate;
      this.startListeningDebounced();

      return () => {
        delete this.listeners[coinName];
        if (Object.keys(this.listeners).length === 0) {
          this.stopListening();
        }
      }
    }
  }

  const GlobalCoinPriceWS = new CryptoCoinPriceWS();

</script>

<script lang="ts">
  import { type ComponentProps } from "$lib/components/composites/dynamic-layout";
  import { onMount } from "svelte";
  import {
    getKeyedLiveNodeDataStateForName,
    getLiveNodeDataStateForName
  } from "$lib/contexts/liveNodeData.context.svelte";

  let {
    layoutContext
  }: ComponentProps = $props();

  let node = $derived(layoutContext.node);
  let nodeProps = $derived(node.nodeConfig as CryptoCoinPriceNodeProps);

  let coin = $derived(nodeProps.coin ?? "bitcoin");
  let price = $state(0);

  const liveDataState = getKeyedLiveNodeDataStateForName('cryptoCoinPrice', coin, 0);

  $effect(() => {
    const cleanup = GlobalCoinPriceWS.addListener(coin, (newPrice) => {
      price = newPrice;

      liveDataState.current = newPrice;
    });

    return () => {
      cleanup();
    };
  });
</script>

<style>
  .crypto-coin-price {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 1rem;
    border: 1px solid #ddd;
    border-radius: 0.5rem;
    box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
  }

  .coin-name {
    font-size: 1.5rem;
    font-weight: bold;
    margin-bottom: 0.5rem;
  }

  .coin-price {
    font-size: 2rem;
    color: #4caf50;
  }
</style>

<div class="crypto-coin-price">
  <div class="coin-name">{coin}</div>
  <div class="coin-price">${price}</div>
</div>
