<script lang="ts" module>
  import type { JsonSchemaParts, SchemaPartsGenerator } from "./jsonSchemaTypes";
  import { hasTitleSchema } from "./shared-schemas/title-schema";
  import type { DynamicLayoutNode } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { Rss } from "@lucide/svelte";

  export interface RSSReaderNodeProps {
    rssUrl: string;
    entriesPerPage: number;
  }

  const isRSSReaderNodeSchema = () => (): JsonSchemaParts => {
    return {
      dataTab: "general",
      schemaProperties: {
        rssUrl: {
          type: "string",
          title: "RSS URL"
        },
        entriesPerPage: {
          type: "number",
          title: "Entries Per Page",
          default: 5
        }
      },
      requiredProperties: ["rssUrl", "entriesPerPage"],
      uiSchemaProperties: {},
      getFormValuesByNode: (node: DynamicLayoutNode) => {
        const nodeProps = node.nodeConfig as RSSReaderNodeProps;
        return {
          rssUrl: nodeProps.rssUrl,
          entriesPerPage: nodeProps.entriesPerPage ?? 5
        };
      },
      setToNode: (node: DynamicLayoutNode, values: any) => {
        node.nodeConfig.rssUrl = values.rssUrl;
        node.nodeConfig.entriesPerPage = values.entriesPerPage;
      }
    };
  };

  export const SCHEMA_PARTS: SchemaPartsGenerator = (context) => [
    hasTitleSchema(true),
    isRSSReaderNodeSchema()
  ];

  export const RSSReaderNodeInfo = {
    nodeType: "rssReader",
    schemaParts: SCHEMA_PARTS,
    iconComponent: Rss
  };
</script>

<script lang="ts">
  import { type ComponentProps } from "$lib/components/composites/dynamic-layout";
  import { getLabel } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { getCachedRSSData, setCachedRSSData } from "../../state/rssCacheManager";


  let {
    layoutContext
  }: ComponentProps = $props();

  let node = $derived(layoutContext.node);
  let label = $derived(getLabel(layoutContext.node));

  let nodeProps = $derived(node.nodeConfig as RSSReaderNodeProps);

  let rssUrl = $derived(nodeProps?.rssUrl ?? "");
  let entriesPerPage = $derived(nodeProps?.entriesPerPage ?? 5);

  let currentPage = $state(1);

  // Fetch and display RSS feed content
  let rssEntries = $state<{ title: string; description: string; imageUrl: string | null }[]>([]);

  async function fetchRSSContent() {
    const cachedData = getCachedRSSData(rssUrl);
    if (cachedData) {
      rssEntries = cachedData;
      return;
    }

    try {
      const response = await fetch(rssUrl);
      const text = await response.text();
      const parser = new DOMParser();
      const xmlDoc = parser.parseFromString(text, "application/xml");
      const items = xmlDoc.querySelectorAll("item");
      const entries = Array.from(items).map((item) => {
        const title = item.querySelector("title")?.textContent ?? "";
        const description = item.querySelector("description")?.textContent ?? "";
        const imageUrl = item.querySelector("enclosure")?.getAttribute("url") ?? null;
        return { title, description, imageUrl };
      });
      rssEntries = entries;
      setCachedRSSData(rssUrl, entries);
    } catch (error) {
      console.error("Failed to fetch RSS content:", error);
      rssEntries = [];
    }
  }

  $effect(() => {
    if (rssUrl) {
      fetchRSSContent();
    }
  });

  function changePage(newPage: number) {
    if (newPage >= 1 && newPage <= totalPages) {
      currentPage = newPage;
    }
  }

  let totalPages = $derived(Math.ceil(rssEntries.length / entriesPerPage));
  let paginatedEntries = $derived(rssEntries.slice((currentPage - 1) * entriesPerPage, currentPage * entriesPerPage));
</script>

<style>
  .rss-entry {
    padding: 1rem;
    border: 1px solid #ccc;
    margin-bottom: 1rem;
    border-radius: 0.5rem;
  }

  .rss-entry h4 {
    margin: 0;
    font-size: 1.25rem;
    color: #333;
  }

  .rss-entry p {
    margin: 0.5rem 0;
    color: #666;
  }

  .rss-entry img {
    max-width: 100%;
    height: auto;
    border-radius: 0.5rem;
  }

  .pagination {
    display: flex;
    justify-content: center;
    margin-top: 1rem;
  }

  .pagination button {
    padding: 0.5rem 1rem;
    margin: 0 0.25rem;
    border: 1px solid #ccc;
    background-color: #f9f9f9;
    cursor: pointer;
  }

  .pagination button:disabled {
    cursor: not-allowed;
    opacity: 0.5;
  }
</style>

<div>
  <h3>{label}</h3>
  {#if paginatedEntries.length > 0}
    {#each paginatedEntries as entry}
      <div class="rss-entry">
        <h4>{entry.title}</h4>
        <p>{entry.description}</p>
        {#if entry.imageUrl}
          <img src={entry.imageUrl} alt={entry.title} />
        {/if}
      </div>
    {/each}
    <div class="pagination">
      <button on:click={() => changePage(currentPage - 1)} disabled={currentPage === 1}>Previous</button>
      <button on:click={() => changePage(currentPage + 1)} disabled={currentPage === totalPages}>Next</button>
    </div>
  {:else}
    <p>Loading RSS content...</p>
  {/if}
</div>
